+
+function clock(): Clock {
+  const c: Clock = {
+    at: 1_000_000,
+    timers: [],
+    advance(ms) {
+      const target = c.at + ms;
+      for (;;) {
+        const due = c.timers.filter((t) => t.live && t.at <= target).sort((a, b) => a.at - b.at)[0];
+        if (due === undefined) break;
+        c.at = due.at;
+        due.live = false;
+        due.run();
+      }
+      c.at = target;
+    },
+  };
+  return c;
